securityRules.rules:
rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    function isAuthenticated() { return request.auth != null; }
    function getUserData() { return get(/databases/$(database)/documents/users/$(request.auth.uid)).data; }
    function hasRole(role) { return isAuthenticated() && (request.auth.token.role == role || getUserData().rol == role); }
    function isAdmin() { return hasRole('admin') || hasRole('administrador'); }
    function isTherapist() { return hasRole('terapeuta') || isAdmin(); }
    function isOwner(userId) { return isAuthenticated() && request.auth.uid == userId; }

    match /users/{userId} {
      allow read: if isAuthenticated() && (isOwner(userId) || isAdmin() || isTherapist());
      allow create: if isAuthenticated();
      allow update, delete: if isAuthenticated() && (isOwner(userId) || isAdmin());
    }
    match /clientes/{clienteId} {
      allow read: if isAuthenticated();
      allow create, update, delete: if isAuthenticated() && (isOwner(clienteId) || isAdmin());
    }
    match /terapeutas/{terapeutaId} {
      allow read: if isAuthenticated();
      allow create, update, delete: if isAuthenticated() && (isOwner(terapeutaId) || isAdmin());
    }
    match /reservas/{reservaId} {
      allow read, create, update: if isAuthenticated();
      allow delete: if isAuthenticated() && isAdmin();
    }
    match /pagos/{pagoId} {
      allow read, create: if isAuthenticated();
      allow update, delete: if isAuthenticated() && isAdmin();
    }
  }
}
